FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilitacion del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado : INT := 0; (* 0: Verde, 1: Amarillo, 2: Rojo *)
    tFase : TON; (* Temporizador para las fases del semaforo *)
    tParpadeo : TON; (* Temporizador para el parpadeo *)
    estadoBlink : BOOL := TRUE; (* Estado de la luz intermitente *)
END_VAR

IF habilitado THEN
    (* Secuencia normal del semaforo *)
    CASE estado OF
        0: tFase(IN := TRUE, PT := T#20S); (* Verde *)
        1: tFase(IN := TRUE, PT := T#4S);  (* Amarillo *)
        2: tFase(IN := TRUE, PT := T#15S); (* Rojo *)
    END_CASE;

    (* Cambio de fase al terminar el tiempo *)
    IF tFase.Q THEN
        estado := (estado + 1) MOD 3;
        tFase(IN := FALSE); (* Reiniciar temporizador para la siguiente fase *)
    END_IF;

    (* Asignacion de salidas *)
    luzV := (estado = 0);
    luzA := (estado = 1);
    luzR := (estado = 2);

    (* Reiniciar variables del modo intermitente *)
    tParpadeo(IN := FALSE);
    estadoBlink := TRUE;
ELSE
    (* Modo deshabilitado: Amarillo intermitente *)
    estado := 0; (* Preparar reinicio en verde *)
    tFase(IN := FALSE); (* Reiniciar temporizador de secuencia *)

    (* Generador de pulsos de 1 segundo *)
    tParpadeo(IN := TRUE, PT := T#1S);
    IF tParpadeo.Q THEN
        estadoBlink := NOT estadoBlink;
        tParpadeo(IN := FALSE); (* Reiniciar temporizador de parpadeo *)
    END_IF;

    (* Asignacion de salidas *)
    luzV := FALSE;
    luzR := FALSE;
    luzA := estadoBlink;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilita la secuencia normal del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado     : INT;  (* Estado de la secuencia: 0=verde, 1=amarillo, 2=rojo *)
    tFase      : TON; (* Temporizador de cada fase normal *)
    tBlink     : TP;  (* Temporizador de pulso para amarillo intermitente *)
    bBlinkTrig : BOOL; (* Flanco para relanzar el pulso intermitente *)
END_VAR

IF habilitado THEN
    (* --- Secuencia normal: verde -> amarillo -> rojo -> verde --- *)

    CASE estado OF

        0: (* VERDE 20 s *)
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            tFase(IN := TRUE, PT := T#20S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#20S); (* Resetea temporizador *)
                estado := 1;
            END_IF;

        1: (* AMARILLO 4 s *)
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            tFase(IN := TRUE, PT := T#4S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#4S);
                estado := 2;
            END_IF;

        2: (* ROJO 15 s *)
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            tFase(IN := TRUE, PT := T#15S);
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#15S);
                estado := 0; (* Reinicia ciclo *)
            END_IF;

        ELSE
            estado := 0; (* Estado invalido: vuelve a verde *)

    END_CASE;

    (* Asegura que el temporizador de blink quede inactivo *)
    bBlinkTrig := FALSE;
    tBlink(IN := FALSE, PT := T#1S);

ELSE
    (* --- Modo inhabilitado: amarillo intermitente 1 s ON / 1 s OFF --- *)
    luzV := FALSE;
    luzR := FALSE;

    (* Relanza el pulso cada vez que expira *)
    tBlink(IN := bBlinkTrig, PT := T#1S);

    IF NOT tBlink.Q AND NOT bBlinkTrig THEN
        (* Pulso inactivo y no disparado: lanzar nuevo pulso *)
        bBlinkTrig := TRUE;
    END_IF;

    IF tBlink.Q THEN
        (* Pulso expirado: apagar disparo para permitir nuevo ciclo *)
        bBlinkTrig := FALSE;
    END_IF;

    luzA := tBlink.Q; (* Amarillo encendido durante el pulso activo *)

    (* Al rehabilitar, reinicia la secuencia en verde *)
    tFase(IN := FALSE, PT := T#20S);
    estado := 0;

END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Semaforo habilitado *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    tVerde : TP; (* Temporizador para luz verde *)
    tAmarillo : TP; (* Temporizador para luz amarilla *)
    tRojo : TP; (* Temporizador para luz roja *)
    tIntermitente : TP; (* Temporizador para luz amarilla intermitente *)
    estado : INT := 0; (* Estado actual del semáforo *)
END_VAR

(* Secuencia normal del semáforo *)
IF habilitado THEN
    CASE estado OF
        0: (* Verde *)
            tVerde(IN := TRUE, PT := T#20S);
            luzV := tVerde.Q;
            luzA := FALSE;
            luzR := FALSE;
            IF tVerde.Q THEN
                estado := 1;
            END_IF
        1: (* Amarillo *)
            tAmarillo(IN := TRUE, PT := T#4S);
            luzV := FALSE;
            luzA := tAmarillo.Q;
            luzR := FALSE;
            IF tAmarillo.Q THEN
                estado := 2;
            END_IF
        2: (* Rojo *)
            tRojo(IN := TRUE, PT := T#15S);
            luzV := FALSE;
            luzA := FALSE;
            luzR := tRojo.Q;
            IF tRojo.Q THEN
                estado := 0;
            END_IF
    END_CASE
ELSE
    (* Modo intermitente *)
    tIntermitente(IN := TRUE, PT := T#1S);
    luzV := FALSE;
    luzA := tIntermitente.Q;
    luzR := FALSE;
    IF tIntermitente.Q THEN
        tIntermitente(IN := FALSE);
    END_IF
END_IF

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Señal para habilitar la secuencia normal *)
END_VAR

VAR_OUTPUT
    luzV : BOOL; (* Luz Verde *)
    luzA : BOOL; (* Luz Amarilla *)
    luzR : BOOL; (* Luz Roja *)
END_VAR

VAR
    estado : INT := 0; (* 0: Intermitente, 1: Verde, 2: Amarillo, 3: Rojo *)
    timerSecuencia : TON; (* Temporizador para la secuencia normal *)
    timerIntermitente : TON; (* Temporizador para el parpadeo *)
    estadoBlink : BOOL := FALSE; (* Estado auxiliar para la luz intermitente *)
    flancoHabilitado : R_TRIG; (* Detector de flanco de subida *)
END_VAR

(* Detectar cuando se activa la entrada para reiniciar la secuencia en verde *)
flancoHabilitado(CLK := habilitado);
IF flancoHabilitado.Q THEN
    estado := 1;
    timerSecuencia(IN := FALSE); (* Reset del temporizador principal *)
ELSIF NOT habilitado THEN
    estado := 0; (* Si se deshabilita, pasa a modo intermitente *)
END_IF;

(* Máquina de estados del semáforo *)
CASE estado OF
    0: (* Modo Deshabilitado: Amarillo intermitente *)
        luzV := FALSE;
        luzR := FALSE;
        timerSecuencia(IN := FALSE); (* Mantener apagado el timer principal *)

        (* Generador de pulsos: 1s encendido, 1s apagado *)
        timerIntermitente(IN := NOT timerIntermitente.Q, PT := T#1S);
        IF timerIntermitente.Q THEN
            estadoBlink := NOT estadoBlink;
        END_IF;
        luzA := estadoBlink;

    1: (* Modo Normal: Verde (20 segundos) *)
        luzV := TRUE;
        luzA := FALSE;
        luzR := FALSE;
        timerIntermitente(IN := FALSE); (* Reset del timer intermitente *)

        timerSecuencia(IN := TRUE, PT := T#20S);
        IF timerSecuencia.Q THEN
            estado := 2;
            timerSecuencia(IN := FALSE);
        END_IF;

    2: (* Modo Normal: Amarillo (4 segundos) *)
        luzV := FALSE;
        luzA := TRUE;
        luzR := FALSE;

        timerSecuencia(IN := TRUE, PT := T#4S);
        IF timerSecuencia.Q THEN
            estado := 3;
            timerSecuencia(IN := FALSE);
        END_IF;

    3: (* Modo Normal: Rojo (15 segundos) *)
        luzV := FALSE;
        luzA := FALSE;
        luzR := TRUE;

        timerSecuencia(IN := TRUE, PT := T#15S);
        IF timerSecuencia.Q THEN
            estado := 1;
            timerSecuencia(IN := FALSE);
        END_IF;
END_CASE;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL;
END_VAR
VAR_OUTPUT
    luzV : BOOL;
    luzA : BOOL;
    luzR : BOOL;
END_VAR
VAR
    estado : INT := 0; (* 0: Intermitente, 1: Verde, 2: Amarillo, 3: Rojo *)
    timerSecuencia : TON;
    timerParpadeo : TON;
    estadoParpadeo : BOOL;
    rTrigHabilitado : R_TRIG;
    tiempoFase : TIME;
END_VAR

(* Detectar flanco de subida para reiniciar la secuencia en verde *)
rTrigHabilitado(CLK := habilitado);
IF rTrigHabilitado.Q THEN
    estado := 1;
    estadoParpadeo := FALSE; (* Reiniciar estado del parpadeo *)
ELSIF NOT habilitado THEN
    estado := 0;
END_IF;

(* Asignar el tiempo correspondiente a la fase actual *)
CASE estado OF
    1: tiempoFase := T#20S;
    2: tiempoFase := T#4S;
    3: tiempoFase := T#15S;
END_CASE;

(* Temporizador principal de la secuencia (se auto-reinicia al terminar) *)
timerSecuencia(IN := habilitado AND NOT timerSecuencia.Q, PT := tiempoFase);

(* Cambio de estado al completarse el tiempo de la fase *)
IF timerSecuencia.Q THEN
    CASE estado OF
        1: estado := 2;
        2: estado := 3;
        3: estado := 1;
    END_CASE;
END_IF;

(* Temporizador para el parpadeo en modo deshabilitado (1s ON, 1s OFF) *)
timerParpadeo(IN := NOT habilitado AND NOT timerParpadeo.Q, PT := T#1S);
IF timerParpadeo.Q THEN
    estadoParpadeo := NOT estadoParpadeo;
END_IF;

(* Control de las salidas físicas según el estado activo *)
CASE estado OF
    0: (* Deshabilitado: Amarillo intermitente, demás apagadas *)
        luzV := FALSE;
        luzA := estadoParpadeo;
        luzR := FALSE;
    1: (* Secuencia: Verde *)
        luzV := TRUE;
        luzA := FALSE;
        luzR := FALSE;
    2: (* Secuencia: Amarillo *)
        luzV := FALSE;
        luzA := TRUE;
        luzR := FALSE;
    3: (* Secuencia: Rojo *)
        luzV := FALSE;
        luzA := FALSE;
        luzR := TRUE;
END_CASE;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilitacion del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    tCiclo : TON; (* Temporizador para el ciclo del semaforo *)
    tIntermitente : TON; (* Temporizador para el amarillo intermitente *)
    estado : INT; (* Estado del semaforo *)
    intermitente : BOOL; (* Estado de la luz amarilla intermitente *)
END_VAR

(* Logica del semaforo *)
IF habilitado THEN
    (* Control del ciclo del semaforo *)
    CASE estado OF
        0: (* Luz verde *)
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            tCiclo(IN := TRUE, PT := T#20S);
            IF tCiclo.Q THEN
                estado := 1;
                tCiclo(IN := FALSE);
            END_IF;
        1: (* Luz amarilla *)
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            tCiclo(IN := TRUE, PT := T#4S);
            IF tCiclo.Q THEN
                estado := 2;
                tCiclo(IN := FALSE);
            END_IF;
        2: (* Luz roja *)
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            tCiclo(IN := TRUE, PT := T#15S);
            IF tCiclo.Q THEN
                estado := 0;
                tCiclo(IN := FALSE);
            END_IF;
    END_CASE;
ELSE
    (* Control del amarillo intermitente *)
    luzV := FALSE;
    luzR := FALSE;
    tIntermitente(IN := TRUE, PT := T#1S);
    IF tIntermitente.Q THEN
        intermitente := NOT intermitente;
        tIntermitente(IN := FALSE);
    END_IF;
    luzA := intermitente;
    estado := 0; (* Reiniciar ciclo al habilitar *)
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilitacion del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado : INT := 0; (* 0: Intermitente, 1: Verde, 2: Amarillo, 3: Rojo *)
    tSecuencia : TON;  (* Temporizador para la secuencia normal *)
    tBlink1 : TON;     (* Temporizador 1 para parpadeo (tiempo encendido) *)
    tBlink2 : TON;     (* Temporizador 2 para parpadeo (tiempo apagado) *)
    tiempoActual : TIME;
    transicion : BOOL;
END_VAR

(* Control de estado principal *)
IF NOT habilitado THEN
    estado := 0;
ELSIF estado = 0 THEN
    estado := 1; (* Reinicia en verde al habilitarse *)
END_IF;

(* Asignacion de tiempos y luces segun el estado *)
CASE estado OF
    0: (* Amarillo intermitente *)
        luzV := FALSE;
        luzA := NOT tBlink1.Q;
        luzR := FALSE;
    1: (* Verde *)
        tiempoActual := T#20S;
        luzV := TRUE;
        luzA := FALSE;
        luzR := FALSE;
    2: (* Amarillo *)
        tiempoActual := T#4S;
        luzV := FALSE;
        luzA := TRUE;
        luzR := FALSE;
    3: (* Rojo *)
        tiempoActual := T#15S;
        luzV := FALSE;
        luzA := FALSE;
        luzR := TRUE;
END_CASE;

(* Actualizacion de temporizadores *)
tSecuencia(IN := habilitado AND NOT transicion, PT := tiempoActual);
transicion := tSecuencia.Q;

tBlink1(IN := (estado = 0) AND NOT tBlink2.Q, PT := T#1S);
tBlink2(IN := tBlink1.Q, PT := T#1S);

(* Transiciones de la secuencia normal *)
IF transicion THEN
    CASE estado OF
        1: estado := 2;
        2: estado := 3;
        3: estado := 1;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK

