END_VAR

(* ─────────────────────────────────────────────────────────────
   Lógica principal
   ───────────────────────────────────────────────────────────── *)

IF NOT habilitado THEN
    (* ── Modo amarillo intermitente ─────────────────────────── *)

    (* Reiniciar temporizadores de secuencia normal *)
    tVerde(IN    := FALSE, PT := T#20S);
    tAmarillo(IN := FALSE, PT := T#4S);
    tRojo(IN     := FALSE, PT := T#15S);

    (* Reiniciar estado para que al habilitar arranque en verde *)
    estado := 0;

    (* Temporizador de 1 s para el parpadeo *)
    tIntermitente(IN := TRUE, PT := T#1S);

    IF tIntermitente.Q THEN
        (* Conmutar el bit de parpadeo y reiniciar el temporizador *)
        parpadeo          := NOT parpadeo;
        tIntermitente(IN  := FALSE, PT := T#1S); (* Reset *)
        tIntermitente(IN  := TRUE,  PT := T#1S); (* Rearranque *)
    END_IF;

    (* Salidas: solo amarillo parpadea *)
    luzV := FALSE;
    luzA := parpadeo;
    luzR := FALSE;

ELSE
    (* ── Modo secuencia normal ───────────────────────────────── *)

    (* Detener y resetear el temporizador de intermitente *)
    tIntermitente(IN := FALSE, PT := T#1S);
    parpadeo := FALSE;

    CASE estado OF

        0: (* ── Verde ── *)
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;

            tVerde(IN := TRUE, PT := T#20S);

            IF tVerde.Q THEN
                tVerde(IN := FALSE, PT := T#20S); (* Reset *)
                estado := 1;                       (* Pasar a amarillo *)
            END_IF;

        1: (* ── Amarillo ── *)
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;

            tAmarillo(IN := TRUE, PT := T#4S);

            IF tAmarillo.Q THEN
                tAmarillo(IN := FALSE, PT := T#4S); (* Reset *)
                estado := 2;                         (* Pasar a rojo *)
            END_IF;

        2: (* ── Rojo ── *)
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;

            tRojo(IN := TRUE, PT := T#15S);

            IF tRojo.Q THEN
                tRojo(IN := FALSE, PT := T#15S); (* Reset *)
                estado := 0;                      (* Volver a verde *)
            END_IF;

        ELSE
            (* Estado inválido: reiniciar en verde *)
            estado := 0;

    END_CASE;

END_IF;

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilita la secuencia normal *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado : INT := 0; (* 0: Verde, 1: Amarillo, 2: Rojo *)
    tVerde : TON;      (* Temporizador luz verde *)
    tAmarillo : TON;   (* Temporizador luz amarilla *)
    tRojo : TON;       (* Temporizador luz roja *)
    tBlink1 : TON;     (* Temporizador intermitencia ON *)
    tBlink2 : TON;     (* Temporizador intermitencia OFF *)
END_VAR

(* Control de estados y reinicio *)
IF NOT habilitado THEN
    estado := 0; (* Reinicia la secuencia a verde si se deshabilita *)
ELSIF estado = 0 AND tVerde.Q THEN
    estado := 1;
ELSIF estado = 1 AND tAmarillo.Q THEN
    estado := 2;
ELSIF estado = 2 AND tRojo.Q THEN
    estado := 0;
END_IF;

(* Temporizadores de la secuencia normal *)
tVerde(IN := habilitado AND (estado = 0), PT := T#20S);
tAmarillo(IN := habilitado AND (estado = 1), PT := T#4S);
tRojo(IN := habilitado AND (estado = 2), PT := T#15S);

(* Temporizadores del modo intermitente (1s ON / 1s OFF) *)
tBlink1(IN := NOT habilitado AND NOT tBlink2.Q, PT := T#1S);
tBlink2(IN := tBlink1.Q, PT := T#1S);

(* Asignacion de salidas *)
luzV := habilitado AND (estado = 0);
luzR := habilitado AND (estado = 2);
luzA := (habilitado AND (estado = 1)) OR (NOT habilitado AND NOT tBlink1.Q);

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL;
END_VAR
VAR_OUTPUT
    luzV : BOOL;
    luzA : BOOL;
    luzR : BOOL;
END_VAR
VAR
    estado : INT := 0; (* 0: Intermitente, 1: Verde, 2: Amarillo, 3: Rojo *)
    timerSecuencia : TON;
    timerIntermitente : TON;
    trigHabilitado : R_TRIG;
    estadoAmarillo : BOOL;
    tiempoActual : TIME;
    resetTimer : BOOL;
END_VAR

(* Detectar flanco de subida para reiniciar la secuencia en verde *)
trigHabilitado(CLK := habilitado);
IF trigHabilitado.Q THEN
    estado := 1;
    resetTimer := TRUE;
    estadoAmarillo := FALSE; (* Reiniciar estado del intermitente *)
END_IF;

(* Si se desactiva la entrada, pasar a modo intermitente *)
IF NOT habilitado THEN
    estado := 0;
END_IF;

(* Lógica de salidas y selección de tiempos según el estado *)
CASE estado OF
    0: (* Modo deshabilitado: Amarillo intermitente (1s ON, 1s OFF) *)
        luzV := FALSE;
        luzR := FALSE;
        tiempoActual := T#0S;

        (* Temporizador para alternar la luz amarilla cada 1 segundo *)
        timerIntermitente(IN := NOT timerIntermitente.Q, PT := T#1S);
        IF timerIntermitente.Q THEN
            estadoAmarillo := NOT estadoAmarillo;
        END_IF;
        luzA := estadoAmarillo;

    1: (* Secuencia: Verde (20s) *)
        luzV := TRUE;
        luzA := FALSE;
        luzR := FALSE;
        tiempoActual := T#20S;

    2: (* Secuencia: Amarillo (4s) *)
        luzV := FALSE;
        luzA := TRUE;
        luzR := FALSE;
        tiempoActual := T#4S;

    3: (* Secuencia: Rojo (15s) *)
        luzV := FALSE;
        luzA := FALSE;
        luzR := TRUE;
        tiempoActual := T#15S;
END_CASE;

(* Ejecución del temporizador principal de la secuencia *)
timerSecuencia(IN := (estado > 0) AND NOT resetTimer, PT := tiempoActual);

(* Limpiar la señal de reset para que el temporizador inicie en el siguiente ciclo *)
IF resetTimer THEN
    resetTimer := FALSE;
END_IF;

(* Transición al siguiente estado cuando se cumple el tiempo *)
IF timerSecuencia.Q THEN
    resetTimer := TRUE; (* Forzar el reinicio del temporizador *)
    CASE estado OF
        1: estado := 2;
        2: estado := 3;
        3: estado := 1;
    END_CASE;
END_IF;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; // Variable de entrada que indica si el semáforo está habilitado
END_VAR

VAR_OUTPUT
    luzV : BOOL; // Salida para la luz verde
    luzA : BOOL; // Salida para la luz amarilla
    luzR : BOOL; // Salida para la luz roja
END_VAR

VAR
    estado : INT := 0; // Variable de estado para controlar la secuencia
    contador : TON; // Contador de tiempo
    intermitente : BOOL := FALSE; // Variable para controlar el estado intermitente
END_VAR

// Inicialización del contador de tiempo
contador(IN := FALSE, PT := T#1S);

// Lógica del semáforo
CASE estado OF
    0: // Estado verde
        IF habilitado THEN
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            contador(IN := TRUE, PT := T#20S);
            IF contador.Q THEN
                estado := 1;
            END_IF;
        ELSE
            estado := 3; // Cambia a estado intermitente
        END_IF;

    1: // Estado amarillo
        IF habilitado THEN
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            contador(IN := TRUE, PT := T#4S);
            IF contador.Q THEN
                estado := 2;
            END_IF;
        ELSE
            estado := 3; // Cambia a estado intermitente
        END_IF;

    2: // Estado rojo
        IF habilitado THEN
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            contador(IN := TRUE, PT := T#15S);
            IF contador.Q THEN
                estado := 0;
            END_IF;
        ELSE
            estado := 3; // Cambia a estado intermitente
        END_IF;

    3: // Estado intermitente
        luzV := FALSE;
        luzA := intermitente;
        luzR := FALSE;
        contador(IN := TRUE, PT := T#1S);
        IF contador.Q THEN
            intermitente := NOT intermitente; // Cambia el estado intermitente
            contador(IN := FALSE); // Reinicia el contador
            IF habilitado THEN
                estado := 0; // Vuelve al estado verde si se habilita nuevamente
            END_IF;
        END_IF;

END_CASE

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Entrada para habilitar el semáforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    tVerde : TP; (* Temporizador para luz verde *)
    tAmarillo : TP; (* Temporizador para luz amarilla *)
    tRojo : TP; (* Temporizador para luz roja *)
    tIntermitente : TP; (* Temporizador para luz amarilla intermitente *)
    estado : INT := 0; (* Estado actual del semáforo *)
END_VAR

(* Secuencia normal del semáforo *)
IF habilitado THEN
    CASE estado OF
        0: (* Verde *)
            tVerde(IN := TRUE, PT := T#20S);
            luzV := tVerde.Q;
            luzA := FALSE;
            luzR := FALSE;
            IF tVerde.Q THEN
                estado := 1;
            END_IF
        1: (* Amarillo *)
            tAmarillo(IN := TRUE, PT := T#4S);
            luzV := FALSE;
            luzA := tAmarillo.Q;
            luzR := FALSE;
            IF tAmarillo.Q THEN
                estado := 2;
            END_IF
        2: (* Rojo *)
            tRojo(IN := TRUE, PT := T#15S);
            luzV := FALSE;
            luzA := FALSE;
            luzR := tRojo.Q;
            IF tRojo.Q THEN
                estado := 0;
            END_IF
    END_CASE
ELSE
    (* Modo intermitente cuando no está habilitado *)
    tIntermitente(IN := TRUE, PT := T#1S);
    luzV := FALSE;
    luzA := tIntermitente.Q;
    luzR := FALSE;
    IF tIntermitente.Q THEN
        tIntermitente(IN := FALSE);
    END_IF
END_IF
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilitacion del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    tCiclo : TON; (* Temporizador para el ciclo del semaforo *)
    tIntermitente : TON; (* Temporizador para el amarillo intermitente *)
    estado : INT; (* Estado del semaforo *)
    intermitente : BOOL; (* Estado del intermitente *)
END_VAR

(* Logica del semaforo ciclico *)
IF habilitado THEN
    (* Control del ciclo del semaforo *)
    CASE estado OF
        0: (* Verde 20 segundos *)
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            tCiclo(IN := TRUE, PT := T#20S);
            IF tCiclo.Q THEN
                estado := 1;
                tCiclo(IN := FALSE);
            END_IF;
        1: (* Amarillo 4 segundos *)
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            tCiclo(IN := TRUE, PT := T#4S);
            IF tCiclo.Q THEN
                estado := 2;
                tCiclo(IN := FALSE);
            END_IF;
        2: (* Rojo 15 segundos *)
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            tCiclo(IN := TRUE, PT := T#15S);
            IF tCiclo.Q THEN
                estado := 0;
                tCiclo(IN := FALSE);
            END_IF;
    END_CASE;
ELSE
    (* Amarillo intermitente *)
    luzV := FALSE;
    luzR := FALSE;
    tIntermitente(IN := TRUE, PT := T#1S);
    IF tIntermitente.Q THEN
        intermitente := NOT intermitente;
        tIntermitente(IN := FALSE);
    END_IF;
    luzA := intermitente;
    estado := 0; (* Reinicia el ciclo al habilitar *)
END_IF;
END_FUNCTION_BLOCK

