FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; // Entrada que habilita o deshabilita el semáforo
END_VAR

VAR_OUTPUT
    luzV : BOOL; // Salida para la luz verde
    luzA : BOOL; // Salida para la luz amarilla
    luzR : BOOL; // Salida para la luz roja
END_VAR

VAR
    estado : INT := 0; // Variable de estado para el semáforo
    timer : TON; // Timer para controlar los tiempos
    tiempoVerde : TIME := T#20S; // Tiempo verde
    tiempoAmarillo : TIME := T#4S; // Tiempo amarillo
    tiempoRojo : TIME := T#15S; // Tiempo rojo
    tiempoAmarilloIntermitente : TIME := T#1S; // Tiempo amarillo intermitente
    contadorAmarilloIntermitente : INT := 0; // Contador para el amarillo intermitente
END_VAR

// Inicialización del timer
timer(IN := FALSE, PT := tiempoVerde);

// Máquina de estados
CASE estado OF
    0: // Estado verde
        luzV := TRUE;
        luzA := FALSE;
        luzR := FALSE;
        IF habilitado THEN
            timer(IN := TRUE);
            IF timer.Q THEN
                timer(IN := FALSE);
                estado := 1; // Cambiar a estado amarillo
            END_IF
        ELSE
            estado := 3; // Cambiar a estado amarillo intermitente
        END_IF

    1: // Estado amarillo
        luzV := FALSE;
        luzA := TRUE;
        luzR := FALSE;
        IF habilitado THEN
            timer(IN := TRUE, PT := tiempoAmarillo);
            IF timer.Q THEN
                timer(IN := FALSE);
                estado := 2; // Cambiar a estado rojo
            END_IF
        ELSE
            estado := 3; // Cambiar a estado amarillo intermitente
        END_IF

    2: // Estado rojo
        luzV := FALSE;
        luzA := FALSE;
        luzR := TRUE;
        IF habilitado THEN
            timer(IN := TRUE, PT := tiempoRojo);
            IF timer.Q THEN
                timer(IN := FALSE);
                estado := 0; // Cambiar a estado verde
            END_IF
        ELSE
            estado := 3; // Cambiar a estado amarillo intermitente
        END_IF

    3: // Estado amarillo intermitente
        luzV := FALSE;
        luzA := contadorAmarilloIntermitente MOD 2 = 0;
        luzR := FALSE;
        IF habilitado THEN
            estado := 0; // Reiniciar a estado verde
        ELSE
            contadorAmarilloIntermitente := contadorAmarilloIntermitente + 1;
            timer(IN := TRUE, PT := tiempoAmarilloIntermitente);
        END_IF
END_CASE

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilita la secuencia normal del semáforo *)
END_VAR

VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR

VAR
    (* Temporizadores TON estándar IEC 61131-3 *)
    tVerde      : TON; (* Temporizador fase verde:   20 s *)
    tAmarillo   : TON; (* Temporizador fase amarilla: 4 s *)
    tRojo       : TON; (* Temporizador fase roja:    15 s *)
    tParpadeo   : TON; (* Temporizador parpadeo:      1 s *)

    (* Estado de la máquina de estados *)
    (* 0 = Verde, 1 = Amarillo, 2 = Rojo, 3 = Amarillo intermitente *)
    estado      : INT := 0;

    (* Bit auxiliar para el parpadeo del amarillo intermitente *)
    parpadeoOn  : BOOL := FALSE;
END_VAR

(* ─────────────────────────────────────────────────────────────────────────── *)
(*  Lógica principal                                                           *)
(* ─────────────────────────────────────────────────────────────────────────── *)

IF NOT habilitado THEN
    (* ── Modo amarillo intermitente ─────────────────────────────────────── *)

    (* Si veníamos de la secuencia normal, reiniciamos al estado intermitente *)
    IF estado <> 3 THEN
        estado     := 3;
        parpadeoOn := FALSE;
        (* Apagar temporizadores de secuencia normal *)
        tVerde(IN := FALSE, PT := T#20S);
        tAmarillo(IN := FALSE, PT := T#4S);
        tRojo(IN := FALSE, PT := T#15S);
        (* Arrancar temporizador de parpadeo *)
        tParpadeo(IN := FALSE, PT := T#1S);
    END_IF;

    (* Temporizador de parpadeo: alterna cada 1 s *)
    tParpadeo(IN := TRUE, PT := T#1S);
    IF tParpadeo.Q THEN
        parpadeoOn := NOT parpadeoOn; (* Invertir estado del parpadeo *)
        tParpadeo(IN := FALSE, PT := T#1S); (* Reiniciar temporizador *)
    END_IF;

    (* Salidas: solo amarillo parpadea, verde y rojo apagados *)
    luzV := FALSE;
    luzA := parpadeoOn;
    luzR := FALSE;

ELSE
    (* ── Secuencia normal cíclica ────────────────────────────────────────── *)

    (* Si veníamos del modo intermitente, reiniciar en verde *)
    IF estado = 3 THEN
        estado := 0;
        parpadeoOn := FALSE;
        tParpadeo(IN := FALSE, PT := T#1S); (* Detener parpadeo *)
    END_IF;

    CASE estado OF

        0: (* ── VERDE 20 s ─────────────────────────────────────────────── *)
            tVerde(IN := TRUE, PT := T#20S);
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            IF tVerde.Q THEN
                tVerde(IN := FALSE, PT := T#20S); (* Reiniciar temporizador *)
                estado := 1;                       (* Pasar a amarillo *)
            END_IF;

        1: (* ── AMARILLO 4 s ────────────────────────────────────────────── *)
            tAmarillo(IN := TRUE, PT := T#4S);
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            IF tAmarillo.Q THEN
                tAmarillo(IN := FALSE, PT := T#4S); (* Reiniciar temporizador *)
                estado := 2;                         (* Pasar a rojo *)
            END_IF;

        2: (* ── ROJO 15 s ───────────────────────────────────────────────── *)
            tRojo(IN := TRUE, PT := T#15S);
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            IF tRojo.Q THEN
                tRojo(IN := FALSE, PT := T#15S); (* Reiniciar temporizador *)
                estado := 0;                      (* Volver a verde *)
            END_IF;

        ELSE
            (* Estado inesperado: forzar reinicio en verde *)
            estado := 0;

    END_CASE;

END_IF;

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; // Entrada para habilitar o deshabilitar el semáforo
END_VAR_INPUT

VAR_OUTPUT
    luzV : BOOL; // Salida para la luz verde
    luzA : BOOL; // Salida para la luz amarilla
    luzR : BOOL; // Salida para la luz roja
END_VAR_OUTPUT

VAR
    estado : INT; // Estado actual del semáforo
    temporizador : TON; // Temporizador para controlar los tiempos de las luces
    parpadeo : BOOL; // Estado del parpadeo amarillo
END_VAR

// Inicialización del bloque de función
IF NOT habilitado THEN
    // Si no está habilitado, activar parpadeo amarillo
    luzV := FALSE;
    luzR := FALSE;
    temporizador(IN := TRUE, PT := T#1S);
    parpadeo := temporizador.Q;
    luzA := parpadeo;
ELSE
    // Si está habilitado, seguir la secuencia normal del semáforo
    temporizador(IN := TRUE);
    CASE estado OF
        0: // Luz verde
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            temporizador(PT := T#20S);
            IF temporizador.Q THEN
                estado := 1;
                temporizador(IN := FALSE);
            END_IF;
        1: // Luz amarilla
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            temporizador(PT := T#4S);
            IF temporizador.Q THEN
                estado := 2;
                temporizador(IN := FALSE);
            END_IF;
        2: // Luz roja
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            temporizador(PT := T#15S);
            IF temporizador.Q THEN
                estado := 0;
                temporizador(IN := FALSE);
            END_IF;
    ELSE
        // Reiniciar al estado inicial si el estado es desconocido
        estado := 0;
    END_CASE;
END_IF;
END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Semaforo
VAR_INPUT
    habilitado : BOOL; (* Habilita la secuencia normal del semaforo *)
END_VAR
VAR_OUTPUT
    luzV : BOOL; (* Luz verde *)
    luzA : BOOL; (* Luz amarilla *)
    luzR : BOOL; (* Luz roja *)
END_VAR
VAR
    estado     : INT;  (* Estado de la secuencia: 0=Verde, 1=Amarillo, 2=Rojo *)
    tFase      : TON; (* Temporizador de cada fase de la secuencia normal *)
    tBlink     : TP;  (* Temporizador de pulso para amarillo intermitente *)
    blink      : BOOL; (* Estado actual del parpadeo amarillo *)
    prevHab    : BOOL; (* Valor anterior de habilitado para detectar flancos *)
END_VAR

IF habilitado THEN
    (* --- Secuencia normal: Verde -> Amarillo -> Rojo -> (repite) --- *)

    (* Al detectar flanco ascendente de habilitado, reiniciar en verde *)
    IF NOT prevHab THEN
        estado := 0;
        tFase(IN := FALSE, PT := T#20S); (* Reset del temporizador *)
    END_IF;

    CASE estado OF

        0: (* VERDE: 20 segundos *)
            tFase(IN := TRUE, PT := T#20S);
            luzV := TRUE;
            luzA := FALSE;
            luzR := FALSE;
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#20S); (* Reset *)
                estado := 1;
            END_IF;

        1: (* AMARILLO: 4 segundos *)
            tFase(IN := TRUE, PT := T#4S);
            luzV := FALSE;
            luzA := TRUE;
            luzR := FALSE;
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#4S); (* Reset *)
                estado := 2;
            END_IF;

        2: (* ROJO: 15 segundos *)
            tFase(IN := TRUE, PT := T#15S);
            luzV := FALSE;
            luzA := FALSE;
            luzR := TRUE;
            IF tFase.Q THEN
                tFase(IN := FALSE, PT := T#15S); (* Reset *)
                estado := 0; (* Reinicia ciclo en verde *)
            END_IF;

        ELSE
            estado := 0; (* Estado invalido: volver a verde *)

    END_CASE;

    (* Asegurar que el temporizador de parpadeo quede inactivo *)
    tBlink(IN := FALSE, PT := T#1S);
    blink := FALSE;

ELSE
    (* --- Modo inhabilitado: amarillo intermitente 1s ON / 1s OFF --- *)

    (* Apagar verde y rojo *)
    luzV := FALSE;
    luzR := FALSE;

    (* Asegurar que el temporizador de secuencia quede inactivo *)
    tFase(IN := FALSE, PT := T#20S);

    (* Generar pulso de 1 segundo repetitivo para el parpadeo *)
    tBlink(IN := NOT tBlink.Q, PT := T#1S);

    (* El pulso activo indica amarillo encendido *)
    luzA := tBlink.Q;

END_IF;

(* Guardar estado actual de habilitado para deteccion de flanco en proximo ciclo *)
prevHab := habilitado;

END_FUNCTION_BLOCK
